react = {'default': old['reactions']['default']}
for h, rows in V.items():
    assert len(rows) == 7, h
    react[h] = {t: ['{name}: ' + x for x in r.split('|')] for t, r in zip(TAGS, rows)}
out = {'_about': "Raid writing (Fable, F4). Built by tools/raids_text.py: edit there, not here. The engine reads: boss intro, rooms (three drawn at random from the boss's six; room_pool is the fallback), boss lines, and reactions by hero id (default is the fallback). A room choice rolls one team stat (attack, defense, health, speed, luck). {name} is the hero who reacts, {boss} the boss. The narrator is neutral: no swearing, whatever Smudge's voice setting. Rooms must make sense in any order.",
       'room_pool': old['room_pool'], 'bosses': B, 'reactions': react}
R = json.load(open(os.path.join(ROOT, 'data', 'rules.json')))
ids = {h['id'] for h in R['heroes']}; assert ids <= set(V), ids - set(V)
assert {b['id'] for b in R['raids']['bosses']} == set(B)
for k, b in B.items():
    assert len(b['rooms']) == 6 and len(b['lines']['hit']) >= 3, k
    assert b['weak'] in R['stats'] and b['resist'] in R['stats']
    for r in b['rooms']:
        assert 2 <= len(r['choices']) <= 3
        for c in r['choices']: assert c['stat'] in R['stats'], c
json.dump(out, open(os.path.join(ROOT, 'data', 'raids.json'), 'w'), indent=1, ensure_ascii=False)
print('bosses', len(B), 'rooms', sum(len(b['rooms']) for b in B.values()), 'hero voices', len(V), 'lines', sum(len(l) for v in react.values() for l in v.values()))
